mapper.select:
select c.id, c.job_id, c.user_id, c.reason, c.create_time, u.user_name, u.user_picture, j.title as job_title, e.name as company_name from job_complaint c left join sys_user u on c.user_id = u.user_id left join job j on c.job_id = j.id left join enterprise e on j.enterprise_id = e.id
and c.id = #{id}
and c.job_id = #{jobId}
and c.user_id = #{userId}
and u.user_name like concat('%', #{userName}, '%')
and e.name like concat('%', #{companyName}, '%')
and c.reason like concat('%', #{reason}, '%')
order by c.create_time desc
